def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    # Locate the largest non-background object and the separate marker cells.
    remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    comps = []
    while remaining:
        start = remaining.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if p in remaining:
                    remaining.remove(p)
                    comp.add(p)
                    stack.append(p)
        comps.append(comp)

    pattern = max(comps, key=len)
    markers = [next(iter(c)) for c in comps if len(c) == 1 and c is not pattern]
    if not markers:
        return [row[:] for row in grid]

    r0, r1 = min(r for r,c in pattern), max(r for r,c in pattern)
    c0, c1 = min(c for r,c in pattern), max(c for r,c in pattern)

    # Use the pattern's central cell as the anchor for each marker.
    ar, ac = (r1-r0)//2, (c1-c0)//2
    out = [row[:] for row in grid]
    for mr, mc in markers:
        for r, c in pattern:
            rr = mr + (r-r0) - ar
            cc = mc + (c-c0) - ac
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = grid[r][c]
    return out
